#include <bits/stdc++.h>
#define rep(i,n) for(int i=0; i<(n); i++)
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;

struct Edge { int to, capacity, cost, rev; };

struct Network {
    static const int MAXN = 5010;
    vector<Edge> adj[MAXN];
    int V;
    int h[MAXN], dist[MAXN], prevv[MAXN], preve[MAXN];

    void setup(int n) {
        V = n;
        for (int i=0; i<V; i++) adj[i].clear();
    }

    void addEdge(int from, int to, int cap, int cost) {
        adj[from].push_back({to, cap, cost, (int)adj[to].size()});
        adj[to].push_back({from, 0, -cost, (int)adj[from].size() - 1});
    }

    int minCostFlow(int s, int t, int flow) {
        int totalCost = 0;
        fill(h, h+V, 0);
        while (flow > 0) {
            priority_queue<pii, vector<pii>, greater<pii>> pq;
            fill(dist, dist+V, INT_MAX);
            dist[s] = 0;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i=0; i<(int)adj[v].size(); i++) {
                    Edge &e = adj[v][i];
                    if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INT_MAX) return -1;
            for (int v=0; v<V; v++) h[v] += dist[v];
            int d = flow;
            for (int v=t; v!=s; v=prevv[v]) {
                d = min(d, adj[prevv[v]][preve[v]].capacity);
            }
            flow -= d;
            totalCost += d * h[t];
            for (int v=t; v!=s; v=prevv[v]) {
                Edge &e = adj[prevv[v]][preve[v]];
                e.capacity -= d;
                adj[v][e.rev].capacity += d;
            }
        }
        return totalCost;
    }
};

int main() {
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    int a[50], cnt[50] = {0};
    rep(i,k) scanf("%d", a+i);
    rep(i,k) cnt[a[i]-1]++;
    vector<int> e[50];
    rep(i,m) {
        int x, y; scanf("%d%d", &x, &y);
        x--; y--;
        e[x].push_back(y);
        e[y].push_back(x);
    }
    Network net;
    net.setup(n*100+2);
    rep(i,n) net.addEdge(n*100, i, cnt[i], 0);
    rep(i,100) net.addEdge(i*n, n*100+1, k, c*i);
    rep(i,n) {
        rep(j,99) net.addEdge(j*n+i, (j+1)*n+i, k, 0);
        for (int to: e[i]) {
            rep(j,99) {
                rep(u,k) {
                    int cost = (u+1)*(u+1)*d - u*u*d;
                    net.addEdge(j*n+i, (j+1)*n+to, 1, cost);
                }
            }
        }
    }
    printf("%d\n", net.minCostFlow(n*100, n*100+1, k));
}
